import Link from "next/link";
import {
  ArrowRight,
  Bot,
  BriefcaseBusiness,
  CheckCircle2,
  Code2,
  Layers3,
  LayoutGrid,
  MessageSquareCode,
  Rocket,
  Smartphone,
  Workflow,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Card,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

const services = [
  {
    icon: Bot,
    title: "AI Automation",
    description:
      "Design and build automation systems that reduce manual work, connect tools, and keep operations moving with fewer bottlenecks.",
    points: ["Workflow automation", "AI-assisted operations", "System integration"],
  },
  {
    icon: Code2,
    title: "Full-Stack Web Development",
    description:
      "Create fast, maintainable web applications with clean interfaces, robust APIs, and production-ready architecture.",
    points: ["Modern frontend apps", "Scalable backend systems", "Database architectures"],
  },
  {
    icon: Smartphone,
    title: "Mobile App Development",
    description:
      "Develop powerful, native-quality mobile applications for iOS and Android that deliver seamless and engaging user experiences.",
    points: ["Custom iOS & Android apps", "High-performance UI", "End-to-end app delivery"],
  },
  {
    icon: Workflow,
    title: "Product Systems & Integrations",
    description:
      "Connect payment, analytics, CRM, and internal tools into one coherent product workflow that scales with the business.",
    points: ["Third-party APIs", "Payments", "Admin dashboards"],
  },
];

const process = [
  {
    icon: MessageSquareCode,
    title: "Discover",
    description:
      "Define the problem, scope the work, and map the technical and business requirements.",
  },
  {
    icon: Layers3,
    title: "Build",
    description:
      "Design the system, implement the interface, and ship iteratively with clear feedback loops.",
  },
  {
    icon: Rocket,
    title: "Launch",
    description:
      "Deploy, refine, and support the solution so it performs well in real usage.",
  },
];

const techStack = [
  "React",
  "Next.js",
  "Laravel",
  "Python",
  "TensorFlow",
  "PyTorch",
  "Scikit-learn",
  "Keras",
  "Hugging Face",
  "OpenAI",
  "Agentic AI",
  "RAG AI",
  "Azure",
  "n8n",
  "Zapier",
  "Git",
  "Flutter",
  "WordPress",
  "MySQL",
  "Docker",
  "Kubernetes",
];

export default function ServicesPage() {
  return (
    <main className="min-h-dvh flex flex-col gap-14 relative">
      <section>
        <div className="mx-auto flex w-full max-w-2xl flex-col gap-10">
          <div className="space-y-5">
            <div className="inline-flex items-center gap-2 rounded-full border bg-card/80 px-4 py-2 text-sm text-muted-foreground shadow-sm backdrop-blur">
              <BriefcaseBusiness className="size-4 text-primary" />
              Services
            </div>
            <div className="space-y-4">
              <h1 className="text-4xl font-semibold tracking-tighter sm:text-5xl lg:text-6xl">
                Build the product, automate the work, and keep it scalable.
              </h1>
              <p className="max-w-2xl text-pretty text-muted-foreground md:text-lg">
                I help teams and founders turn ideas into practical software by
                combining automation, product thinking, and production-ready
                engineering.
              </p>
            </div>
            <div className="flex flex-col gap-3 sm:flex-row">
              <Button asChild className="group px-6">
                <Link href="/#contact">
                  Start a project
                  <ArrowRight className="ml-2 size-4 transition-transform group-hover:translate-x-1" />
                </Link>
              </Button>
              <Button asChild variant="outline" className="group px-6">
                <Link href="/projects">
                  View projects
                  <LayoutGrid className="ml-2 size-4 transition-transform group-hover:scale-110" />
                </Link>
              </Button>
            </div>
          </div>

          <div className="flex flex-col gap-12 sm:gap-16 pt-12">
            {services.map((service, index) => {
              const ServiceIcon = service.icon;

              return (
                <article key={service.title} className="relative isolate flex flex-col md:flex-row gap-6 md:gap-8 pb-12 sm:pb-16 border-b-2 border-border last:border-b-0 last:pb-0">
                  {/* Background Number Watermark */}
                  <div className="absolute top-0 right-0 sm:-top-2 sm:-right-4 text-5xl sm:text-7xl font-bold tracking-tighter text-muted-foreground/10 leading-none select-none pointer-events-none -z-10">
                    0{index + 1}
                  </div>

                  <div className="flex-none">
                    <div className="flex size-14 items-center justify-center rounded-full bg-secondary text-foreground backdrop-blur-md">
                      <ServiceIcon className="size-6" />
                    </div>
                  </div>
                  
                  <div className="flex-1 space-y-4 pt-1">
                    <h3 className="text-xl font-bold tracking-tight sm:text-2xl">
                      {service.title}
                    </h3>
                    
                    <p className="max-w-2xl text-base text-muted-foreground leading-relaxed">
                      {service.description}
                    </p>
                    
                    <ul className="grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-3 pt-2 max-w-2xl">
                      {service.points.map((point) => (
                        <li key={point} className="flex items-center gap-2.5 text-sm text-foreground/90">
                          <CheckCircle2 className="size-4 text-foreground/70" />
                          {point}
                        </li>
                      ))}
                    </ul>
                  </div>
                </article>
              );
            })}
          </div>
        </div>
      </section>

      <section>
        <div className="mx-auto w-full max-w-2xl space-y-6">
          <div className="flex items-end justify-between gap-4">
            <div>
              <p className="text-sm font-medium uppercase tracking-[0.2em] text-muted-foreground">
                Working style
              </p>
              <h2 className="mt-2 text-2xl font-semibold tracking-tight sm:text-3xl">
                A simple process with clear outcomes.
              </h2>
            </div>
          </div>

          <div className="grid gap-4 md:grid-cols-3">
            {process.map((item, index) => {
              const ProcessIcon = item.icon;

              return (
                <Card key={item.title} className="border-border/70 bg-card/70">
                  <CardHeader className="space-y-4">
                    <div className="flex items-center justify-between">
                      <div className="inline-flex size-10 items-center justify-center rounded-xl bg-primary text-primary-foreground">
                        <ProcessIcon className="size-4" />
                      </div>
                      <span className="text-sm text-muted-foreground">
                        0{index + 1}
                      </span>
                    </div>
                    <CardTitle className="text-lg">{item.title}</CardTitle>
                    <CardDescription className="text-sm leading-relaxed">
                      {item.description}
                    </CardDescription>
                  </CardHeader>
                </Card>
              );
            })}
          </div>
        </div>
      </section>

      <section>
        <div className="mx-auto w-full max-w-2xl rounded-xl border border-border bg-card p-6 transition-all duration-200 hover:ring-2 hover:ring-muted sm:p-8">
          <div className="space-y-4">
            <div className="inline-flex items-center gap-2 rounded-full border px-3 py-1 text-xs font-medium uppercase tracking-[0.2em] text-muted-foreground">
              <LayoutGrid className="size-3.5" />
              Stack
            </div>
            <h2 className="text-2xl font-semibold tracking-tight sm:text-3xl">
              Tools I use to deliver reliable systems.
            </h2>
            <p className="max-w-xl text-sm leading-relaxed text-muted-foreground">
              I work with a practical stack tuned for fast iteration, solid
              integrations, and maintainable delivery.
            </p>
          </div>

          <div className="mt-6 flex flex-wrap gap-2">
            {techStack.map((tech) => (
              <span
                key={tech}
                className="rounded-full border bg-background px-3 py-1 text-sm text-foreground/80"
              >
                {tech}
              </span>
            ))}
          </div>

          <div className="mt-8 flex flex-col gap-3 sm:flex-row">
            <Button asChild className="group px-6">
              <Link href="/#contact">
                Let&apos;s talk
                <ArrowRight className="ml-2 size-4 transition-transform group-hover:translate-x-1" />
              </Link>
            </Button>
            <Button asChild variant="outline" className="px-6">
              <Link href="/projects">Browse all projects</Link>
            </Button>
          </div>
        </div>
      </section>
    </main>
  );
}